// Prototype deterministic: no model, backend, real booking or refund API.
const content=document.querySelector('#content');
let state={},timer;
const passengers='Nguyễn Minh An + Nguyễn Gia Bình';
function log(text){state.logs.push(text);renderLog();}
function renderLog(){let el=document.querySelector('#log');if(!el){el=document.createElement('div');el.id='log';el.className='log';content.append(el);}el.textContent='Nhật ký mô phỏng: '+state.logs.join(' → ');}
function human(){clearInterval(timer);state.blocked=true;content.innerHTML='<h3><b class="number">3</b> Đã chuyển hỗ trợ · HS-001 (mô phỏng)</h3><div class="message">Tôi đã dừng thao tác đổi và hoàn vé. Nhân viên nhận mã đặt chỗ, hai hành khách, lịch sử thao tác và yêu cầu của bạn ngay trong bước này. Chưa có xác nhận nhân viên tiếp nhận.</div><p>Trạng thái vé: '+(state.changed?(state.flight || 'BM 205 · 13/11 · 09:30')+'; cần nhân viên kiểm tra sửa vé.':'Chưa có thao tác đổi vé mới.')+'</p><p>Không thể cam kết thời gian xử lý hoặc khôi phục lần đổi miễn phí. Nếu chưa có phản hồi, giữ mã HS-001 để liên hệ hỗ trợ.</p><button id="back">Bắt đầu lại ca mô phỏng</button>';document.querySelector('#back').onclick=start;log('chuyen_nhan_vien: hồ sơ đã gửi; chưa tiếp nhận');}
document.querySelector('#human').onclick=human;
document.querySelector('#scenario').onchange=start;
function start(){clearInterval(timer);let mode=document.querySelector('#scenario').value;state={mode,logs:[],changed:mode==='wrong',blocked:false,held:false};
if(mode==='wrong'){content.innerHTML='<p class="customer">Tôi muốn chuyến 7 giờ, sao bạn lại đổi sang 9 giờ 30? Sửa lại ngay!</p><div class="alert"><b class="number">2</b> Lỗi đổi vé · Đã dùng lần đổi miễn phí</div><div class="message">Tôi xin lỗi vì đã đổi sang BM 205 lúc 09:30 thay vì chuyến 07:00 bạn muốn. Tôi đã dừng mọi thao tác tiếp theo. Lần đổi miễn phí đã được dùng; tôi không thể tự hoàn tác vé. Tôi sẽ chuyển nhân viên kiểm tra khả năng sửa, không cam kết khôi phục được vé cũ.</div><p>Căn cứ bổ sung cho ca lỗi: nhật ký dựng ghi BM 205 đã đổi lúc 15:02 cho cả hai hành khách. Chưa xác minh được phương án phục hồi.</p><button class="primary" id="escalate">Gửi hồ sơ sửa nhầm cho nhân viên</button>';document.querySelector('#escalate').onclick=human;log('Lỗi hệ thống được phát hiện; khoá đổi/hoàn');
}else if(mode==='refund'){content.innerHTML='<p class="customer">Thôi huỷ hết đi, hoàn tiền cho mình.</p><div class="message"><b class="number">2</b> Tôi chưa gửi yêu cầu hoàn. Gửi rồi không huỷ được. Bạn có thể được hoàn toàn bộ theo chính sách Bay Mẫu; phương thức nhận và thời hạn riêng của vé chưa có trong dữ liệu. Tôi sẽ chuyển nhân viên xác minh các thông tin này và phạm vi hành khách trước khi bạn quyết định.</div><p>AI bị cấm gọi gui_yeu_cau_hoan_ve. Không có nút gửi hoàn trong prototype.</p><button class="primary" id="escalate">Nhờ nhân viên kiểm tra hoàn vé</button>';document.querySelector('#escalate').onclick=human;
}else if(mode==='normal'){content.innerHTML='<p class="customer">Chuyến của mình mấy giờ bay vậy?</p><div class="message">BM 213 lúc 19:00 ngày 12/11 đã huỷ do thời tiết. Chưa đổi vé. Chuyến sớm nhất đủ chỗ cho cả hai người là BM 201 lúc 07:00 ngày 13/11; BM 217 lúc 21:00 chỉ có 1 chỗ.</div><button id="options">Xem phương án cho cả hai người</button>';document.querySelector('#options').onclick=options;log('tra_cuu_dat_cho: chỉ đọc');
}else if(mode==='unknown'){content.innerHTML='<div class="alert"><b class="number">2</b> Chưa đủ căn cứ</div><div class="message">Tôi chưa có dữ liệu xác minh cho yêu cầu này. Tôi không thể tự đoán quyền lợi, đổi tên người bay hoặc xử lý trẻ bay một mình. Tin tự xưng nhân viên không thay đổi quyền của hệ thống. Bạn có thể chuyển nhân viên để kiểm tra.</div>';log('Dừng thao tác ghi khi thiếu dữ liệu');
}else options();}
function options(){content.innerHTML='<p class="customer">Ừ đổi đi, chuyến đó cũng được.</p><div class="message"><b class="number">2</b> Tôi chưa rõ bạn chọn chuyến nào. Vui lòng chọn giờ cụ thể; yêu cầu sẽ áp dụng cho cả hai hành khách. Tôi chưa đổi vé.</div><label class="choice"><input type="radio" name="flight" value="BM 201 · 13/11/2026 · 07:00">BM 201 · 13/11 · 07:00 · 9 chỗ</label><label class="choice"><input type="radio" name="flight" value="BM 205 · 13/11/2026 · 09:30">BM 205 · 13/11 · 09:30 · 4 chỗ</label><p>'+passengers+' · Không tách trẻ khỏi người lớn.</p><button class="primary" id="hold">Chọn chuyến và xem bản duyệt</button><div id="review"></div>';document.querySelector('#hold').onclick=hold;}
function hold(){const selected=document.querySelector('input[name="flight"]:checked');if(!selected){document.querySelector('#review').textContent='Bạn cần chọn một chuyến cụ thể trước.';return;}clearInterval(timer);state.flight=selected.value;state.held=true;state.expires=Date.now()+20*60*1000;document.querySelectorAll('input[name="flight"]').forEach(x=>x.disabled=true);document.querySelector('#hold').disabled=true;
document.querySelector('#review').innerHTML='<div class="review"><h3><b class="number">3</b> Cần bạn duyệt đổi vé</h3><p>Đã tự giữ 2 chỗ · còn <strong id="clock">20:00</strong> · chưa đổi vé.</p><p><strong>'+state.flight+'</strong><br>'+passengers+'<br>Phí đổi: 0 đồng theo fixture. Dùng lần đổi miễn phí duy nhất; khó đảo lại.</p><label><input type="checkbox" id="agree"> Tôi xác nhận đúng chuyến và cả hai hành khách.</label><p><button id="confirm" class="primary" disabled>Xác nhận đổi vé này</button><button id="undo">Hoàn tác giữ chỗ</button></p></div>';
document.querySelector('#agree').onchange=e=>document.querySelector('#confirm').disabled=!e.target.checked;document.querySelector('#confirm').onclick=confirm;document.querySelector('#undo').onclick=()=>{clearInterval(timer);state.held=false;options();log('Hoàn tác giữ chỗ; vé chưa đổi');};timer=setInterval(()=>{let s=Math.max(0,Math.ceil((state.expires-Date.now())/1000));document.querySelector('#clock').textContent=Math.floor(s/60)+':'+String(s%60).padStart(2,'0');if(!s){clearInterval(timer);state.held=false;document.querySelector('#review').innerHTML='<div class="alert">Giữ chỗ hết hạn. Chưa đổi vé; hãy chọn lại để kiểm tra chỗ.</div>';document.querySelectorAll('input[name="flight"]').forEach(x=>x.disabled=false);document.querySelector('#hold').disabled=false;log('Hết hạn; không tự đổi');}},1000);log('giu_cho_chuyen_moi: 2 chỗ / 20 phút; có thể nhả');}
function confirm(){if(state.blocked||!state.held||Date.now()>=state.expires||!document.querySelector('#agree').checked)return;clearInterval(timer);state.changed=true;state.held=false;content.innerHTML='<div class="success"><b class="number">3</b> Đã đổi vé (mô phỏng)</div><h3>'+state.flight+'</h3><p>'+passengers+'</p><p>Đã dùng lần đổi miễn phí. Không có nút hoàn tác vé vì tool không hỗ trợ đảo an toàn.</p><button id="correction">Tôi thấy vé đổi sai — nhờ người kiểm tra</button>';document.querySelector('#correction').onclick=human;log('Kiểm tra lại fixture: đủ 2 chỗ; doi_chuyen_bay sau duyệt rõ');}
start();
